// Generated by `dart run store_asset_packs:android`. Edits are overwritten;
// change the store_asset_packs: section of pubspec.yaml and run it again.
plugins {
    id("com.android.asset-pack")
}

assetPack {
    packName.set("fast_pack")
    dynamicDelivery {
        deliveryType.set("fast-follow")
    }
}

// The pack's files live in packs/fast_pack/. Syncing them into the
// gitignored src/main/assets keeps a single copy in git. They go under
// fast_pack/ because Play needs every path to be unique across all packs.
val syncPackAssets = tasks.register<Sync>("syncPackAssets") {
    from(file("../../packs/fast_pack"))
    into(layout.projectDirectory.dir("src/main/assets/fast_pack"))
}
tasks.configureEach {
    if (name != "syncPackAssets" && name != "clean") dependsOn(syncPackAssets)
}
